/* Lexer for the FreeCAD Expression language */

/* MODIFIED for libforge_expr (2026-09-15) from FreeCAD src/App/Expression.l at
 * commit 0a45a0a008d4af7a85601016c5ab31bd26c25b22. See MODIFICATIONS.md.
 *
 * Every token rule, every unit and the UTF-8 identifier classes are upstream's.
 * What changed:
 *   * a number or integer the lexer cannot represent no longer THROWS through the
 *     parser (which leaked the partial parse tree); it records why and returns
 *     LEXERROR, which no grammar rule accepts
 *   * a final catch-all rule: upstream had none, so flex's default action ECHOED
 *     an unrecognised character to stdout and SKIPPED it -- "2~" parsed as 2.
 *     Any character no rule matches is now a LEXERROR naming the character
 *   * a carriage return is whitespace
 *   * the unused `functions` stack declaration is removed
 *
 * Regenerate Expression.lex.c with ExpressionParser.sh (flex 2.6.4, -L). */

/* This disables inclusion of unistd.h, which is not available under Visual C++
 * on Win32. The C++ scanner uses STL streams instead. */
